css:
#tongsci1-3-3-4-dice .dc-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-4-dice .dc-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f6f2e8; }
#tongsci1-3-3-4-dice .dc-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-4-dice .dc-stage .now-chip { top: auto; bottom: 8px; left: 14px; font-size: 17px; padding: 6px 14px; }
#tongsci1-3-3-4-dice .dc-panel { gap: 12px; }
#tongsci1-3-3-4-dice .dc-out { margin: 0; font-size: 19px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 6.2em; flex: none; }
#tongsci1-3-3-4-dice .dc-out b { color: var(--accent); }
#tongsci1-3-3-4-dice .dc-def { margin: 0; display: grid; gap: 7px; flex: none; }
#tongsci1-3-3-4-dice .dc-def div { border-left: 6px solid #2f7a4c; background: color-mix(in srgb, #2f7a4c 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 5px 12px; }
#tongsci1-3-3-4-dice .dc-def dt { font: 800 18px var(--f-body); color: #22603b; }
#tongsci1-3-3-4-dice .dc-def dd { margin: 1px 0 0; font-size: 16px; line-height: 1.42; }
section#tongsci1-3-3-4-dice.ex.u-done .dc-def { display: none; }
#tongsci1-3-3-4-dice .u-learn p { font-size: 19px; line-height: 1.5; }

